    g = to_igraph(sub)
    g = g.as_undirected(mode="collapse")
    g = g.simplify(multiple=True, loops=True)

    names = list(g.vs["name"])

    if g.ecount() == 0:
        best = min(names, key=_id_key)
        return {
            "value": 1,
            "witness": [best],
            "method": "no edges: single smallest node id",
        }

    cliques = g.largest_cliques()
    best_size = max(len(c) for c in cliques)
    candidates = []
    for c in cliques:
        if len(c) == best_size:
            members = sorted((names[v] for v in c), key=_id_key)
            candidates.append(members)

    best = min(candidates, key=lambda mem: [_id_key(x) for x in mem])

    return {
        "value": int(best_size),
        "witness": best,
        "method": "igraph largest_cliques (exact maximum clique enumeration), "
                  "lexicographically smallest numeric id list tie-break",
    }

def solve(inputs: dict) -> dict:
    import networkx as nx

    # Build an undirected simple graph from the 'sub' input.
    G = to_networkx(inputs["sub"])
    G = nx.Graph(G)
    G.remove_edges_from(list(nx.selfloop_edges(G)))

    def key(x):
        s = str(x)
        try:
            return (0, int(s), s)
        except ValueError:
            return (1, 0, s)

    nodes = list(G.nodes())

    # No edges: every single node is a clique of size 1.
    if G.number_of_edges() == 0:
        if not nodes:
            return {"value": 0, "witness": [], "method": "empty graph"}
        m = min(nodes, key=key)
        return {
            "value": 1,
            "witness": [m],
            "method": "no edges: smallest node id (numeric comparison)",
        }

    # Every maximum clique is a maximal clique, so enumerate all maximal
    # cliques exhaustively (Bron-Kerbosch with pivoting) and select the best.
    best = None
    best_key = None
    for c in nx.find_cliques(G):
        k = len(c)
        members = sorted(c, key=key)
        mk = [key(x) for x in members]
        if best is None or k > len(best) or (k == len(best) and mk < best_key):
            best = members
            best_key = mk

    return {
        "value": len(best),
        "witness": best,
        "method": "exhaustive maximal clique enumeration (networkx.find_cliques), "
                  "maximum size with lexicographically smallest numeric id list tie-break",
    }

